<script setup lang="ts">
import {computed,defineAsyncComponent,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowUpRight,ArrowRight,Clock3,Smartphone,BookmarkCheck,Fingerprint,SlidersHorizontal,MessagesSquare,Sprout,Compass,Menu,X,Trash2,LoaderCircle,ChevronRight,ShieldCheck} from 'lucide-vue-next'
import ReportView from './Report.vue'
import {api,post,load,save,remove,date,type Draft,type Mode,type Report} from './lib'
const Questionnaire=defineAsyncComponent(()=>import('./Questionnaire.vue'))
const Admin=defineAsyncComponent(()=>import('./Admin.vue'))
const route=useRoute();const router=useRouter();const menu=ref(false);const error=ref('');const loading=ref(true);const reports=ref<Report[]>([]);const drafts=ref<Partial<Record<Mode,Draft>>>({});const example=ref<Report>();const types=ref<any[]>([]);const filters=ref(['','','','']);const resumeLoading=ref(false)
const mode=computed<Mode>(()=>route.query.mode==='full'?'full':'basic');const kind=computed(()=>{if(route.path==='/')return'home';if(route.path==='/test')return'test';if(route.path==='/report')return'report';if(route.path==='/history')return'history';if(route.path==='/resume')return'resume';if(route.path==='/admin')return'admin';if(route.path==='/privacy')return'privacy';if(route.path==='/types'||route.path.startsWith('/types/'))return'types';return'notfound'})
const selected=computed(()=>route.query.example?example.value:(route.query.id?reports.value.find(r=>r.id===route.query.id):reports.value[0]));const typeCode=computed(()=>route.path.split('/')[2]?.toUpperCase()||'');const selectedType=computed(()=>types.value.find(t=>t.code===typeCode.value));const filteredTypes=computed(()=>types.value.filter(t=>filters.value.every((x,i)=>!x||x===t.code[i])))
async function refresh(){try{const [r,b,f]=await Promise.all([load<Report[]>('reports'),load<Draft>('draft:basic'),load<Draft>('draft:full')]);reports.value=r||[];drafts.value={basic:b,full:f}}catch(e){error.value=(e as Error).message}}
async function navigate(){menu.value=false;error.value='';loading.value=true;document.title=`${{home:'认识自己',test:mode.value==='basic'?'99 题精简测试':'300 题详细测试',report:'人格探索报告',history:'本机历史',types:'类型参考',resume:'换设备继续',admin:'内容管理',privacy:'数据与隐私',notfound:'页面未找到'}[kind.value]} · 知序`;try{await refresh();if(kind.value==='types'&&!types.value.length)types.value=await api('/api/types');if(kind.value==='report'&&route.query.example)example.value=await api(`/api/reports/example?mode=${route.query.example==='full'?'full':'basic'}`);if(kind.value==='resume'&&!resumeLoading.value)await restoreResume()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function restoreResume(){const token=route.hash.slice(1);if(!token){error.value='续答链接不完整，请在原设备重新生成链接。';return}resumeLoading.value=true;history.replaceState(history.state,'',`${location.pathname}${location.search}`);try{const r=await post('/api/resume-sessions/claim',{token});const existing=await load<Draft>(`draft:${r.draft.mode}`);if(existing&&existing.id!==r.draft.id&&Object.keys(existing.answers).length&&!confirm('这台设备已有同版本类型的草稿。载入续答链接将替换它，继续吗？')){await router.replace(`/test?mode=${r.draft.mode}`);return}await save(`draft:${r.draft.mode}`,{...r.draft,updatedAt:new Date().toISOString(),resume:{token,revision:r.revision,expires:r.expires}});await router.replace(`/test?mode=${r.draft.mode}`)}finally{resumeLoading.value=false}}
async function deleteReport(id:string){if(!confirm('删除这份本机报告？删除后无法从历史恢复。'))return;await save('reports',reports.value.filter(r=>r.id!==id));await refresh()}
async function clearHistory(){if(!confirm('清空这台浏览器的全部报告？当前未完成草稿会保留。'))return;await save('reports',[]);await refresh()}
async function deleteDraft(which:Mode){const draft=drafts.value[which];if(!draft||!confirm('删除此草稿？已保存的历史报告不受影响。'))return;try{if(draft.resume)await api('/api/resume-sessions/current',{method:'DELETE',body:JSON.stringify({token:draft.resume.token})});await remove(`draft:${which}`);await refresh()}catch(e){error.value=(e as Error).message}}
async function upgrade(report:Report){const full=await load<Draft>('draft:full');if(full&&Object.keys(full.answers).length&&!confirm('本机已有详细版草稿。要继续现有草稿吗？取消可返回报告。'))return;await router.push('/test?mode=full')}
function escape(e:KeyboardEvent){if(e.key==='Escape')menu.value=false}
watch(()=>route.fullPath,()=>void navigate())
onMounted(()=>{void navigate();window.addEventListener('atlas-storage',refresh);window.addEventListener('keydown',escape)})
onBeforeUnmount(()=>{window.removeEventListener('atlas-storage',refresh);window.removeEventListener('keydown',escape)})
</script>

<template>
 <div class="site-shell">
  <a href="#main" class="skip-link">跳到主要内容</a>
  <header class="site-header no-print"><div class="header-inner"><RouterLink to="/" class="brand" aria-label="知序首页"><span class="brand-symbol">知</span><span>知序<small>SELF ATLAS</small></span></RouterLink><nav class="desktop-nav" aria-label="主导航"><RouterLink to="/" :class="{active:kind==='home'||kind==='test'}">人格探索</RouterLink><RouterLink to="/types" :class="{active:kind==='types'}">16 类型参考</RouterLink><RouterLink to="/history" :class="{active:kind==='history'}">本机历史</RouterLink></nav><div class="header-caption">每一种你，都值得被理解。</div><button class="icon-button mobile-menu" :aria-expanded="menu" aria-controls="mobile-nav" :aria-label="menu?'收起导航':'展开导航'" @click="menu=!menu"><X v-if="menu" :size="23"/><Menu v-else :size="23"/></button></div><nav v-if="menu" id="mobile-nav" class="mobile-nav" aria-label="手机导航"><RouterLink to="/">人格探索</RouterLink><RouterLink to="/types">16 类型参考</RouterLink><RouterLink to="/history">本机历史</RouterLink></nav></header>
  <main id="main">
   <div v-if="error" class="page app-error no-print"><div class="alert error" role="alert">{{error}}<button class="text-button" @click="navigate">重试</button></div></div>
   <template v-if="kind==='home'">
    <section class="hero page"><div class="hero-copy"><span class="eyebrow"><i class="dot"></i>一次关于自己的认真探索</span><h1 class="serif">读懂自己，<br>从一个<span class="underlined accent">选择</span>开始。</h1><p class="hero-description">你如何获得能量、看待世界、做出决定？<br>在日常的选择里，找到属于你的人格坐标。</p><div class="button-row"><RouterLink class="primary" to="/test?mode=basic">精简测试 · 99 题 <ArrowUpRight :size="17"/></RouterLink><RouterLink class="secondary" to="/test?mode=full">详细测试 · 300 题 <ArrowUpRight :size="17"/></RouterLink></div><div class="hero-facts"><span><Smartphone :size="15"/>手机 · 平板 · 电脑</span><span><BookmarkCheck :size="15"/>可暂停继续</span><span><Fingerprint :size="15"/>无需注册</span></div></div><div class="atlas-art" aria-label="人格的四个维度：能量、信息、决策和生活方式"><div class="atlas-caption">A SMALL ATLAS OF YOU <span>✳</span></div><span class="orbit orbit-one" aria-hidden="true"></span><span class="orbit orbit-two" aria-hidden="true"></span><div class="personality-tile tile-i"><span>01 / ENERGY</span><strong>I</strong><small>向内，找回能量</small></div><div class="personality-tile tile-n"><span>02 / INFORMATION</span><strong>N</strong><small>看见更多可能</small></div><div class="personality-tile tile-f"><span>03 / DECISIONS</span><strong>F</strong><small>让价值参与选择</small></div><div class="personality-tile tile-p"><span>04 / LIFESTYLE</span><strong>P</strong><small>为未知留一点空白</small></div><div class="atlas-foot">16 种类型 · 无数种你 <i class="dot"></i></div></div></section>
    <section v-if="drafts.basic||drafts.full" class="page draft-banner"><article v-for="which in (['basic','full'] as const)" :key="which" v-show="drafts[which]" class="resume-banner"><BookmarkCheck :size="20"/><div><strong>{{which==='basic'?'精简':'详细'}}版草稿</strong><p>已答 {{Object.keys(drafts[which]?.answers||{}).length}} / {{which==='basic'?99:300}} 题</p></div><RouterLink :to="`/test?mode=${which}`" class="text-button">继续 / 回看 <ArrowRight :size="16"/></RouterLink></article></section>
    <section class="page home-plans"><div class="section-heading"><h2>选择适合你的探索深度</h2><span class="eyebrow">ONE START, TWO WAYS TO EXPLORE</span></div><div class="test-plans"><article class="plan surface"><div class="plan-top"><span class="eyebrow">了解四维偏好</span><span><Clock3 :size="14"/>约 15–25 分钟</span></div><h3>精简测试 <strong>99<small> 题</small></strong></h3><p>从 I/E、S/N、T/F、J/P 四个维度，认识自己的日常倾向。</p><ul><li>四维分析与优势盲点</li><li>具体建议与 7 天行动</li><li>之后可沿用答案继续深入</li></ul><RouterLink to="/test?mode=basic" class="secondary">开始精简测试 <ArrowRight :size="16"/></RouterLink></article><article class="plan surface deep-plan"><div class="plan-top"><span class="eyebrow">把理解带进生活</span><span><Clock3 :size="14"/>约 50–80 分钟 · 可分次</span></div><h3>详细测试 <strong>300<small> 题</small></strong></h3><p>基础人格与深化观察，进一步探索职业发展、社交和恋爱关系。</p><ul><li>99 基础＋21 深化＋三个专项各 60 题</li><li>已有同版本基础答案，只补答 201 题</li><li>专项建议与 30 天成长计划</li></ul><RouterLink to="/test?mode=full" class="primary">开始详细测试 <ArrowRight :size="16"/></RouterLink></article></div><p class="fineprint time-note">预计时间不含休息，实际因阅读与思考节奏而异。</p></section>
    <section class="page home-features"><div class="section-heading"><h2>比四个字母，更了解你</h2><RouterLink to="/report?example=full" class="text-button">查看详细报告示例 <ArrowUpRight :size="16"/></RouterLink></div><div class="feature-grid"><article><span class="feature-icon"><SlidersHorizontal :size="22"/></span><h3>看清你的偏好</h3><p>从四个核心维度出发，也看见接近均衡、随场景变化的倾向。</p></article><article><span class="feature-icon"><MessagesSquare :size="22"/></span><h3>走进真实的日常</h3><p>详细版用专项情境题探索职业、社交与恋爱，建议有回答依据。</p></article><article><span class="feature-icon"><Sprout :size="22"/></span><h3>带走成长的方法</h3><p>每条重点建议包含具体行动与复盘方式，从理解走向可持续的小改变。</p></article></div><div class="gentle-note"><Compass :size="19"/><span>性格是一张地图，帮助你探索自己，而每一步由你决定。</span></div></section>
    <section class="page faq"><div class="section-heading"><h2>开始之前，你可能想了解</h2></div><details><summary>99 题与 300 题有什么区别？</summary><p>99 题探索四维偏好并给出日常建议。300 题包含这 99 题，再增加 21 题人格深化，以及职业、社交和恋爱各 60 题；专项建议依据各自的回答生成。</p></details><details><summary>可以分次完成或换设备继续吗？</summary><p>可以。草稿默认保存在同一浏览器；换设备时，在答题页主动选择“换设备”，生成有效期 7 天的续答链接或二维码。仅在自己的设备打开。</p></details><details><summary>没有工作或恋爱经历，也能回答吗？</summary><p>可以按真实偏好回答需求类问题。需要亲历经验而不适合你的专项题，可选“不适用”。有效回答不足的主题会明确说明。</p></details><details><summary>这是官方 MBTI 测试吗？</summary><p>这是原创的 MBTI 风格探索性问卷，尚未经过标准化心理测量验证。结果用于自我了解，不能作为医学诊断、招聘筛选或职业和伴侣选择的唯一依据。</p></details><details><summary>报告和答案保存在哪里？</summary><p>报告和草稿默认保存在本机浏览器，最近保留 10 份报告。只有主动开启换设备续答，草稿才会加密临时保存到服务器。清除浏览器数据可能删除本机记录。</p></details></section>
   </template>
   <Questionnaire v-else-if="kind==='test'" :key="mode" :mode="mode"/>
   <template v-else-if="kind==='report'"><div v-if="loading" class="page loading-state"><LoaderCircle class="spin"/>正在读取报告…</div><ReportView v-else-if="selected" :key="selected.id" :report="selected" :preview="!!route.query.example" @upgrade="upgrade"/><div v-else class="page empty-state surface"><h1>这份报告不在当前浏览器中</h1><p>报告保存在完成测试时使用的浏览器。你也可以开启新的探索。</p><RouterLink to="/" class="primary">选择测试</RouterLink></div></template>
   <section v-else-if="kind==='history'" class="page history-page"><div class="page-heading"><div><span class="eyebrow">YOUR OWN RECORDS</span><h1>本机历史</h1></div><button v-if="reports.length" class="secondary" @click="clearHistory">清空报告</button></div><p class="muted">仅在当前浏览器保存最近 10 份报告。清理浏览器数据会影响这些记录；重要报告请另存 PDF。</p><h2 v-if="drafts.basic||drafts.full">草稿</h2><div class="history-list"><article v-for="which in (['basic','full'] as const)" :key="which" v-show="drafts[which]" class="surface history-row"><div><h3>{{which==='basic'?'精简 99 题':'详细 300 题'}}</h3><p>已答 {{Object.keys(drafts[which]?.answers||{}).length}} 题 · {{drafts[which]?date(drafts[which]!.updatedAt):''}}</p></div><div class="button-row"><RouterLink :to="`/test?mode=${which}`" class="secondary">继续 / 回看</RouterLink><button class="icon-button" aria-label="删除此草稿" @click="deleteDraft(which)"><Trash2 :size="18"/></button></div></article></div><h2>报告</h2><div v-if="!reports.length" class="empty-state surface"><Compass :size="30"/><h3>你的探索，从这里开始</h3><p>完成测试后，报告会出现在这里。</p><RouterLink to="/" class="primary">选择测试 <ArrowRight :size="16"/></RouterLink></div><div class="history-list"><article v-for="r in reports" :key="r.id" class="surface history-row"><div class="history-type">{{r.type}}</div><div class="history-copy"><h3>{{r.name}}</h3><p>{{date(r.createdAt)}} · {{r.mode==='basic'?'99 题':'300 题'}}</p><div class="history-dimensions"><span v-for="d in r.dimensions" :key="d.key">{{d.key}} {{d.score}}%</span></div></div><div class="button-row"><RouterLink :to="`/report?id=${r.id}`" class="secondary">阅读报告</RouterLink><button class="icon-button" aria-label="删除此报告" @click="deleteReport(r.id)"><Trash2 :size="18"/></button></div></article></div></section>
   <section v-else-if="kind==='types'" class="page types-page"><div class="page-heading"><div><span class="eyebrow">SIXTEEN WAYS, MANY POSSIBILITIES</span><h1>{{selectedType?`${selectedType.code} · ${selectedType.name}`:'16 类型参考'}}</h1></div><RouterLink v-if="selectedType" to="/types" class="text-button">全部类型</RouterLink></div><p class="muted">类型是理解偏好的入口。每个人都比四个字母更丰富，以下为原创组合解读，不对类型做优劣或稀有度排名。</p><template v-if="selectedType"><div class="type-profile surface"><span class="profile-code serif accent">{{selectedType.code}}</span><h2 class="serif">{{selectedType.name}}</h2><p>{{selectedType.dimensions.join('，')}}。这些描述是可能的习惯，不代表能力上限。</p><h3>可以试试的四个小行动</h3><article v-for="(tip,i) in selectedType.tips" :key="tip" class="profile-tip"><span>0{{i+1}}</span><p>{{tip}}</p></article><div class="gentle-note"><Compass :size="20"/><span>先对照实际经历，保留适合的解释；不必为了符合类型而改变自己。</span></div></div><RouterLink to="/test?mode=basic" class="primary">探索我的偏好 <ArrowRight :size="16"/></RouterLink></template><template v-else><div class="type-filters"><label v-for="(pair,i) in [['I','E'],['S','N'],['T','F'],['J','P']]" :key="i" class="field">{{['能量','信息','决策','节奏'][i]}}<select v-model="filters[i]"><option value="">不限</option><option v-for="letter in pair" :key="letter" :value="letter">{{letter}}</option></select></label></div><div v-if="loading" class="loading-state"><LoaderCircle class="spin"/>正在加载类型…</div><div class="type-grid"><RouterLink v-for="t in filteredTypes" :key="t.code" :to="`/types/${t.code}`" class="type-card surface"><span class="serif">{{t.code}}</span><h2>{{t.name}}</h2><p>{{t.dimensions.slice(0,2).join('，')}}</p><span class="text-button">了解这种偏好 <ArrowRight :size="15"/></span></RouterLink></div></template></section>
   <Admin v-else-if="kind==='admin'"/>
   <section v-else-if="kind==='resume'" class="page empty-state"><LoaderCircle v-if="resumeLoading" class="spin"/><h1>{{resumeLoading?'正在恢复你的探索…':'换设备继续'}}</h1><p>请使用原设备答题页生成的完整续答链接。链接有效期为 7 天。</p></section>
   <section v-else-if="kind==='privacy'" class="page legal-page"><span class="eyebrow">YOUR DATA, YOUR CHOICE</span><h1>数据与结果说明</h1><article class="surface prose-panel"><h2>本机记录</h2><p>草稿、答案与最近 10 份报告默认保存在当前浏览器。可以在本机历史里删除。隐私浏览模式或清理网站数据可能删除记录。</p><h2>报告计算</h2><p>提交时将答案临时发送到服务器计算报告，不长期保存原始答案，不记录到访问日志和错误追踪。匿名统计只包含测试版本、日期与开始 / 完成事件，不包含客户身份。</p><h2>主动换设备</h2><p>选择换设备后，加密草稿临时保存在服务器，续答链接有效期 7 天，可以撤销；测试完成后删除临时副本。持有链接的人可以恢复草稿，请勿公开分享。</p><h2>如何使用结果</h2><p>原创 MBTI 风格问卷尚未经过标准化心理测量验证。四维和专项位置用于描述本次回答，不代表能力、准确率或诊断。职业与关系建议需要结合技能、经历、现实条件和双方协商。</p><h2>保存和分享</h2><p>完整报告默认不公开。打印 PDF 和下载摘要由你主动操作；摘要可选择是否包含行动建议。请在分享前检查希望公开的范围。</p></article></section>
   <section v-else class="page empty-state"><h1>这条路暂时没有页面</h1><RouterLink to="/" class="primary">回到首页</RouterLink></section>
  </main>
  <footer class="site-footer no-print"><div><RouterLink to="/" class="footer-brand">知序 · 把理解，留给每一种自己。</RouterLink><p>原创 MBTI 风格探索 · 用于自我了解，非官方量表或心理诊断</p></div><nav aria-label="页脚导航"><RouterLink to="/privacy">数据与说明</RouterLink><RouterLink to="/history">本机历史</RouterLink><RouterLink to="/admin">内容管理</RouterLink></nav></footer>
 </div>
</template>
